def f(x, y):
    return x*x + x*y + y*y - 4*x - 5*y + 7

def grad(x, y, h=1e-5):
    gx = (f(x + h, y) - f(x - h, y)) / (2 * h)
    gy = (f(x, y + h) - f(x, y - h)) / (2 * h)
    return round(gx, 6), round(gy, 6)

def siniflandir(a, b, c):          # H = [[a,b],[b,c]]
    det = a * c - b * b
    if det > 0 and a > 0:
        return "yerel minimum"
    if det > 0 and a < 0:
        return "yerel maksimum"
    if det < 0:
        return "eyer noktasi"
    return "belirsiz"

for p in [(0, 0), (1, 2), (2, 2)]:
    print(p, grad(*p))
print("H = [[2,1],[1,2]] ->", siniflandir(2, 1, 2))
print("H = [[2,4],[4,2]] ->", siniflandir(2, 4, 2))
print("H = [[-2,0],[0,-3]] ->", siniflandir(-2, 0, -3))

